"""Build an offline HTML viewer. It never performs inference or invents predictions."""
import json
from visual_demo.results import ROOT,load_results,GRID,RUNS,LABELS,rows,audit_results

def main():
    data=load_results();audit_results(data)
    payload={'runs':RUNS,'labels':LABELS,'grid':GRID,'summary':rows(data),'results':{
        r:{'clean':data[r]['evaluation']['clean']['accuracy'],
           'conditions':{k:v['accuracy'] for k,v in data[r]['evaluation']['per_condition'].items()}} for r in RUNS}}
    html=TEMPLATE.replace('__DATA__',json.dumps(payload).replace('</','<\\/'))
    (ROOT/'OPEN_RESULTS.html').write_text(html,encoding='utf-8');print('Built OPEN_RESULTS.html')
TEMPLATE='''<!DOCTYPE html><html lang="en"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TINA · Robustness evidence</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f4f6f7;color:#182b36;font:16px/1.5 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:40px 28px}header{border-top:5px solid #176b87;padding-top:24px}.eyebrow{color:#176b87;letter-spacing:2px;font-size:12px;font-weight:750}h1{font-size:clamp(29px,4vw,45px);letter-spacing:-1.3px;line-height:1.15;max-width:820px;margin:12px 0}h2{font-size:21px;letter-spacing:-.3px}p{color:#52636d}.notice{padding:12px 0;border-bottom:1px solid #cbd7dd;font-size:14px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:25px 0}.metric{padding:18px 0;border-bottom:2px solid #bdcdd4}.metric strong{display:block;font-size:32px;letter-spacing:-1px}.metric span{font-size:12px;color:#52636d}.panel{background:white;border:1px solid #dce4e8;padding:24px;margin:22px 0;border-radius:8px}.controls{display:flex;gap:16px;flex-wrap:wrap;align-items:end}label{font-size:13px;color:#52636d}select{display:block;min-width:200px;margin-top:5px;padding:10px;background:white;border:1px solid #a9bbc4;border-radius:4px;font:inherit;color:#182b36}svg{width:100%;height:auto;display:block}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:12px;text-align:right;border-bottom:1px solid #dce4e8}th:first-child,td:first-child{text-align:left}th{font-size:12px;color:#52636d}.legend{display:flex;gap:22px;flex-wrap:wrap;font-size:13px}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px}.small{font-size:13px}.tablewrap{overflow-x:auto}button{padding:10px 16px;border:1px solid #176b87;color:white;background:#176b87;border-radius:4px;font:inherit;cursor:pointer}footer{margin-top:28px;color:#52636d;font-size:13px}.takeaway{font-size:20px;max-width:900px;color:#182b36}.sr{position:absolute;left:-9999px}@media(max-width:700px){main{padding:24px 16px}.metrics{grid-template-columns:1fr 1fr}.panel{padding:16px}th,td{padding:9px}}
</style><main><header><div class="eyebrow">TINA / THESIS DEMONSTRATION</div><h1>What happens when a traffic sign becomes harder to see?</h1><p>Explore your saved experiment results across six degradations and three severity levels.</p></header>
<div class="notice"><b>Saved results explorer.</b> These values come from your uploaded evaluation files. This page does not run the model. Use <code>app.py</code> with your trained checkpoint for live image predictions.</div>
<div class="metrics"><div class="metric"><span>PROPOSED AWARE · CLEAN</span><strong>91.25%</strong></div><div class="metric"><span>MEAN DEGRADED ACCURACY</span><strong>73.98%</strong></div><div class="metric"><span>GAIN OVER CLEAN-ONLY</span><strong>+18.21 pp</strong></div><div class="metric"><span>ARCHIVED TEST SAMPLES</span><strong>7,950</strong></div></div>
<p class="takeaway">The same compact architecture retains more accuracy on degraded inputs after degradation-aware training, with a small clean-image accuracy cost.</p>
<section class="panel"><h2>Explore robustness by severity</h2><div class="controls"><label>Image degradation<select id="kind"></select></label><label>Comparison<select id="which"><option value="proposed">Proposed aware vs clean-only</option><option value="all">All four models</option></select></label></div><p id="settings" class="small"></p><svg id="chart" viewBox="0 0 940 360" role="img" aria-label="Accuracy by degradation severity"></svg><div id="legend" class="legend"></div><p class="small">Hover over a point for the saved accuracy. Lines connect discrete test settings; they do not represent continuous or new measurements.</p></section>
<section class="panel"><h2>Model comparison</h2><div class="tablewrap"><table><thead><tr><th>Model</th><th>Clean (%)</th><th>Degraded mean (%)</th><th>R</th><th>Parameters</th></tr></thead><tbody id="table"></tbody></table></div><p class="small">R = mean degraded accuracy / clean accuracy. It is not the confidence of a single prediction.</p><button id="csv">Download comparison CSV</button></section>
<section class="panel"><h2>What to show your supervisor</h2><ol><li>Explain the saved comparison above: aware versus clean-only isolates the training strategy.</li><li>Open the Streamlit app and load your actual <code>best.keras</code>.</li><li>Upload a cropped sign, set a known class ID, and increase degradation severity.</li><li>Compare predictions and confidence on the same pixels; show failures as well as successes.</li><li>Use the optional Grad-CAM overlay to discuss coarse class-sensitive regions.</li></ol><p class="small">Your upload contains no model checkpoint or original test images. Trained inference must wait until you supply these files. The classifier assigns one of 43 class IDs; it does not locate signs in a full road scene.</p></section>
<footer>Source: results/&lt;run&gt;/eval.json in Tina (3).zip. Archived counts and arithmetic were checked; training provenance and track-disjointness were not independently reproduced. Dummy smoke-test outputs are excluded. This file works offline.</footer></main>
<script>const D=__DATA__;const colors=['#176b87','#ce642d','#5b7466','#8b659b'];const titles={fog:'Fog',motion_blur:'Motion blur',low_light:'Low light',gaussian_noise:'Gaussian noise',rain:'Rain',occlusion:'Occlusion'};const kind=document.querySelector('#kind');Object.keys(D.grid).forEach(k=>{let o=document.createElement('option');o.value=k;o.textContent=titles[k];kind.append(o)});
document.querySelector('#table').innerHTML=D.summary.map(r=>`<tr><td>${r.Model}</td><td>${r.Clean.toFixed(2)}</td><td>${r.Degraded.toFixed(2)}</td><td>${r.R.toFixed(3)}</td><td>${r.Parameters.toLocaleString()}</td></tr>`).join('');
function draw(){let k=kind.value,levels=D.grid[k],indices=document.querySelector('#which').value==='all'?[0,1,2,3]:[0,1];document.querySelector('#settings').textContent='Settings, low to high severity: '+levels.join(' / ');let s='';const y=v=>300-v*2.5;for(let v=0;v<=100;v+=20)s+=`<line x1="65" y1="${y(v)}" x2="890" y2="${y(v)}" stroke="#e3eaed"/><text x="50" y="${y(v)+5}" text-anchor="end" fill="#52636d" font-size="13">${v}%</text>`;let xs=[130,475,820];['Low','Medium','High'].forEach((t,j)=>{s+=`<text x="${xs[j]}" y="330" text-anchor="middle" fill="#52636d" font-size="14">${t}</text>`});indices.forEach(i=>{let vals=levels.map(v=>100*D.results[D.runs[i]].conditions[k+'/'+v]);s+=`<polyline points="${vals.map((v,j)=>xs[j]+','+y(v)).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="3"/>`;vals.forEach((v,j)=>s+=`<circle cx="${xs[j]}" cy="${y(v)}" r="6" fill="${colors[i]}"><title>${D.labels[i]} · ${levels[j]}: ${v.toFixed(2)}%</title></circle>`)});document.querySelector('#chart').innerHTML=s;document.querySelector('#legend').innerHTML=indices.map(i=>`<span><i class="dot" style="background:${colors[i]}"></i>${D.labels[i]}</span>`).join('')}
kind.onchange=draw;document.querySelector('#which').onchange=draw;draw();document.querySelector('#csv').onclick=()=>{let csv='Model,Clean accuracy percent,Mean degraded accuracy percent,R,Parameters\\n'+D.summary.map(r=>[r.Model,r.Clean,r.Degraded,r.R,r.Parameters].join(',')).join('\\n');let a=document.createElement('a'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=u;a.download='tina_saved_comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
</script></html>'''
if __name__=='__main__':main()
